WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pl_t_parallel'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '并行与串行', 'kp-pl-t-parallel', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "工序衔接与并行"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "能同时干的事，坚决同时干。总时间取决于最长的那件事（木桶效应）。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“洗水壶1分，烧水15分，洗茶杯2分，拿茶叶1分。怎么安排最快？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心战法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "找出“必须串行”的主干道（洗壶 -> 烧水）。然后在耗时最长的“烧水 15 分钟”的等待期里，把所有能并行的琐事（洗杯子、拿茶叶）全部塞进去！"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "总时间 = 洗水壶(1) + 烧水(15) = 16 分钟。泡茶不用等水烧开。"}]}]}$$ AS jsonb), NULL, '并行与串行的核心考点与实战推导。', category_node.id, CAST('["数量关系", "并行与串行"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pl_t_parallel", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
